record.field:
# WRONG - Odoo 16 and earlier field name
${vals}=    Create Dictionary
...    product_id=${product_id}
...    product_uom=${uom_id}
...    product_uom_qty=1
${line_id}=    Create Record    sale.order.line    &{vals}

# CORRECT - Odoo 17+ field name
${vals}=    Create Dictionary
...    product_id=${product_id}
...    product_uom_id=${uom_id}
...    product_uom_qty=1
${line_id}=    Create Record    sale.order.line    &{vals}

# CORRECT - proper types
${partner_id}=    Set Variable    ${5}
${order_vals}=    Create Dictionary
...    partner_id=${partner_id}
...    order_line=[(0, 0, {'product_id': ${product_id}, 'product_uom_qty': 1})]

# CORRECT - set source fields, not computed
${vals}=    Create Dictionary
...    partner_id=${partner_id}
...    order_line=[(0, 0, {'product_id': ${product_id}, 'price_unit': 1500.00, 'product_uom_qty': 1})]
${id}=    Create Record    sale.order    &{vals}
# amount_total will be computed automatically from order lines

# WRONG - variable may not exist in teardown if test fails
Test Something
    ${order_id}=    Create Record    sale.order    partner_id=${partner_id}
    # If this fails, ${order_id} doesn't exist for teardown
    [Teardown]    Delete Record    sale.order    ${order_id}

# CORRECT - initialize variables at start
Test Something
    # Initialize with safe default
    ${order_id}=    Set Variable    ${EMPTY}

    # Now create
    ${order_id}=    Create Record    sale.order    partner_id=${partner_id}

    # Teardown handles empty value safely
    [Teardown]    Run Keyword If    '${order_id}' != '${EMPTY}'
    ...    Run Keyword And Ignore Error    Delete Record    sale.order    ${order_id}
